// Extract and normalize the user question from incoming webhook
const payload = $json.body || $json;
const message = (payload.message || payload.question || payload.text || '').trim();
const topicSlug = payload.topicSlug || null;

if (!message) {
  return [{
    json: {
      error: 'No question provided.',
      answer: null,
      sources: []
    }
  }];
}

return [{
  json: {
    message,
    topicSlug,
    has_question: true
  }
}];

// Extract the embedding vector from OpenAI response
const embedding = $json.data[0].embedding;
const question = $('Normalize Chat Input').first().json.message;
const topicSlug = $('Normalize Chat Input').first().json.topicSlug;

return [{
  json: {
    vector: embedding,
    question,
    topicSlug
  }
}];

// Hybrid search: check if vector results are sparse, supplement with keyword SQL fallback
// Replicates features/chat/lib/hybridSearch.js logic
const vectorResponse = $json;
const questionData = $('Extract Question Vector').first().json;
const question = questionData.question;
const topicSlug = questionData.topicSlug;

let vectorResults = vectorResponse.result || [];

// Deduplicate by article_id
const seen = new Set();
const uniqueChunks = [];

for (const chunk of vectorResults) {
  const key = chunk.payload.article_id;
  if (!seen.has(key)) {
    seen.add(key);
    uniqueChunks.push(chunk);
  } else if (uniqueChunks.length < 10) {
    uniqueChunks.push(chunk);
  }
}

// Determine if we need keyword fallback
const needsKeywordFallback = uniqueChunks.length < 3;

// Extract keywords for fallback search (longest words first, same as hybridSearch.js)
const keywords = question
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, '')
  .split(/\s+/)
  .filter(w => w.length > 2)
  .sort((a, b) => b.length - a.length)
  .slice(0, 5);

return [{
  json: {
    vectorChunks: uniqueChunks,
    needsKeywordFallback,
    keywords,
    question,
    topicSlug,
    existingArticleIds: Array.from(seen)
  }
}];

