=SELECT id, title, url, source, category, published_at, summary, content
FROM articles
WHERE title ILIKE {{ "'%" + $json.keywords[0] + "%'" }}
   OR content ILIKE {{ "'%" + $json.keywords[0] + "%'" }}
   OR summary ILIKE {{ "'%" + $json.keywords[0] + "%'" }}
ORDER BY published_at DESC
LIMIT 8;

