// Merge keyword search results with vector results, deduplicate by article_id
const keywordRows = $input.all().map(i => i.json);
const prevData = $('Needs Keyword Fallback?').first().json;
const vectorChunks = prevData.vectorChunks || [];
const existingIds = new Set(prevData.existingArticleIds || []);
const question = prevData.question;

// Convert keyword results to chunk-like format (same as hybridSearch.js)
const dbChunks = keywordRows
  .filter(row => row.id && !existingIds.has(row.id))
  .map(row => ({
    score: 0.5,
    payload: {
      article_id: row.id,
      chunk_text: (row.content || row.summary || '').slice(0, 500),
      title: row.title,
      source: row.source,
      category: row.category,
      published_at: row.published_at ? new Date(row.published_at).toISOString() : null,
      url: row.url
    }
  }));

const mergedChunks = [...vectorChunks, ...dbChunks];

return [{
  json: {
    chunks: mergedChunks,
    question
  }
}];

// Pass through vector-only results when no keyword fallback needed
const prevData = $('Needs Keyword Fallback?').first().json;

return [{
  json: {
    chunks: prevData.vectorChunks || [],
    question: prevData.question
  }
}];

// Build the context string from retrieved chunks — replicates buildContext.js
const data = $input.first().json;
const chunks = data.chunks || [];
const question = data.question;

let context;
if (chunks.length === 0) {
  context = 'No relevant articles found in the database.';
} else {
  const contextParts = chunks.map((c, i) => {
    const p = c.payload;
    const date = p.published_at
      ? new Date(p.published_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
      : 'Date N/A';
    return `[Source ${i + 1}]\nTitle: ${p.title}\nSource: ${p.source}\nDate: ${date}\nURL: ${p.url}\nCategory: ${p.category}\nContent: ${p.chunk_text}`;
  });
  context = contextParts.join('\n\n---\n\n');
}

// Build sources array for the response
const sources = chunks.map(c => ({
  title: c.payload.title,
  url: c.payload.url,
  source: c.payload.source,
  score: c.score
}));

// Deduplicate sources by URL
const seenUrls = new Set();
const uniqueSources = sources.filter(s => {
  if (seenUrls.has(s.url)) return false;
  seenUrls.add(s.url);
  return true;
});

return [{
  json: {
    context,
    question,
    sources: uniqueSources
  }
}];

// Format the final response — matches the app's /api/chat output format
const llmResponse = $json;
const contextData = $('Build RAG Context').first().json;

const answer = llmResponse.choices?.[0]?.message?.content || 'No answer generated.';

return [{
  json: {
    answer,
    question: contextData.question,
    sources: contextData.sources,
    timestamp: new Date().toISOString()
  }
}];

// Return error response for empty questions
return [{
  json: {
    error: 'No question provided.',
    answer: null,
    sources: [],
    timestamp: new Date().toISOString()
  }
}];
